<script setup lang="ts">
/**
 * A pull request the way GitHub states one: what it is, who wrote it, where it goes, what it says.
 *
 * The summary and not the change. The diff has a surface of its own (`files`, ChangeSet) and the
 * checks have theirs; this is the half of a pull request page above them, which is the half a
 * card about something else - a review waiting on you - never showed at all.
 *
 * Nothing is read here. Everything comes off `PrSummary`, which `readArtifacts` fills from the
 * `meta` that already comes back with the diff, so a card drawing this pays for no extra call.
 */
import {
  computed, onBeforeUnmount, onMounted, ref, watch,
} from 'vue';
import type { PrSummary } from '../../focus-artifacts';
import CommentBody from './CommentBody.vue';
import AppIcon from './AppIcon.vue';
import MediaViewer from './MediaViewer.vue';
import { ghAssetUrl } from '../../reviews';
import type { NoteMedia } from '../../focus-review';

const props = withDefaults(defineProps<{
  pr: PrSummary;
  /**
   * The description's checklist, live: a box pressed here is a box ticked on GitHub.
   *
   * The renderer draws a task list as disabled boxes, which is right on a card and wrong on the
   * sheet whose job includes ticking them. The host does the write (PrSheet) - this only says
   * which box, counted in the order they are drawn, which is the order they are written in.
   */
  live?: boolean;
  /**
   * The boxes still being written, drawn as waiting. Every other box stays pressable: they were
   * all disabled while one was written, so a second press in that time did nothing at all.
   */
  ticking?: number[];
}>(), { live: false, ticking: () => [] });

const emit = defineEmits<{ (e: 'tick', n: number): void }>();

/*
 * The boxes, made pressable and numbered. A MutationObserver rather than once on mount, because
 * the body is drawn by a child that redraws on its own when the description changes - and every
 * redraw puts the boxes back to disabled.
 */
const bodyEl = ref<HTMLElement | null>(null);
let watching: MutationObserver | null = null;

function boxes(): HTMLInputElement[] {
  return bodyEl.value ? [...bodyEl.value.querySelectorAll<HTMLInputElement>('input[type="checkbox"]')] : [];
}

function liven(): void {
  if (!props.live) {
    return;
  }
  boxes().forEach((box, n) => {
    box.disabled = false;
    box.classList.toggle('gh__box--waiting', props.ticking.includes(n));
  });
}

function onBodyClick(event: MouseEvent): void {
  const box = (event.target as HTMLElement)?.closest?.('input[type="checkbox"]') as HTMLInputElement | null;

  if (!props.live || !box) {
    return;
  }
  // The tick stays as the browser drew it: the host changes the description at once and writes it
  // behind, and puts the box back only if GitHub refuses (PrSheet). Holding the box until GitHub
  // had agreed is what made a tick take seconds to show.
  emit('tick', boxes().indexOf(box));
}

onMounted(() => {
  liven();
  if (props.live && bodyEl.value && typeof MutationObserver !== 'undefined') {
    watching = new MutationObserver(() => liven());
    watching.observe(bodyEl.value, { childList: true, subtree: true });
  }
});
onBeforeUnmount(() => watching?.disconnect());
watch(() => [props.ticking, props.pr.body], () => liven(), { flush: 'post' });

/** What a recording in the description opens into. The same viewer the findings use. */
const viewer = ref<{ items: NoteMedia[]; at: number } | null>(null);

/**
 * The one word GitHub puts in the badge, and it is not `state` alone.
 *
 * `state` is OPEN for a draft and MERGED for a merge, but a draft is the case that changes what
 * you would do about it - it is not asking for anything yet - so it wins over OPEN. Closed and
 * merged are different endings and GitHub colours them differently; so does this.
 */
const badge = computed(() => {
  if (props.pr.merged) {
    return { word: 'Merged', tone: 'merged' };
  }
  if (props.pr.draft) {
    return { word: 'Draft', tone: 'draft' };
  }
  if (/closed/i.test(props.pr.state)) {
    return { word: 'Closed', tone: 'closed' };
  }

  return { word: 'Open', tone: 'open' };
});

/** What is standing in the way, when GitHub says something is. Nothing for a clean one. */
const blocked = computed(() => {
  const state = String(props.pr.mergeableState || '').toLowerCase();

  if (props.pr.merged || /clean|unknown|has_hooks/.test(state) || !state) {
    return '';
  }

  return { dirty: 'has conflicts', blocked: 'blocked', behind: 'behind the base', unstable: 'checks failing' }[state] || state;
});
</script>

<template>
  <article class="gh">
    <header class="gh__head">
      <span class="gh__badge" :class="`gh__badge--${ badge.tone }`">{{ badge.word }}</span>
      <h3 class="gh__title">{{ pr.title }}</h3>
    </header>

    <!-- The line GitHub puts under the title: who, into what, from what. -->
    <p class="gh__line">
      <strong>{{ pr.author || 'somebody' }}</strong> wants to merge
      <code class="gh__ref">{{ pr.headRef }}</code> into <code class="gh__ref">{{ pr.baseRef }}</code>
    </p>

    <ul class="gh__marks">
      <li class="gh__mark"><code>#{{ pr.number }}</code></li>
      <li class="gh__mark">{{ pr.stat.files }} {{ pr.stat.files === 1 ? 'file' : 'files' }}</li>
      <li class="gh__mark gh__mark--add">+{{ pr.stat.added }}</li>
      <li class="gh__mark gh__mark--del">−{{ pr.stat.removed }}</li>
      <li v-if="pr.approved" class="gh__mark gh__mark--ok">
        <AppIcon name="check" :size="12" />
        approved{{ pr.approvedBy.length ? ` by ${ pr.approvedBy.join(', ') }` : '' }}
      </li>
      <li v-if="blocked" class="gh__mark gh__mark--warn">
        <AppIcon name="alert" :size="12" />
        {{ blocked }}
      </li>
    </ul>

    <!--
      The description, as written.

      Its own scroller: a pull request body on this repository is a filled-in template running
      to several screens, and the tab it is in is one pane of a card.
    -->
    <!-- Through CommentBody, so a recording in the description is a player. See GithubIssue. -->
    <div
      v-if="pr.body"
      ref="bodyEl"
      class="gh__body"
      :class="{ 'gh__body--live': live }"
      @click="onBodyClick"
    >
      <CommentBody :body="pr.body" :asset-url="ghAssetUrl" @open="viewer = $event" />
    </div>
    <p v-else class="gh__none">No description.</p>

    <!-- Over the page, opened on the thumbnail that was clicked. See GithubIssue. -->
    <MediaViewer
      v-if="viewer"
      :items="viewer.items"
      :start="viewer.at"
      @close="viewer = null"
    />
  </article>
</template>

